select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"open_library_id":"OL124895A"},"seq":1,"relation":"authors","after_row":{"id":987364001,"name":"Pierre Louÿs","open_library_id":"OL124895A"},"before_row":null},{"key":{"open_library_id":"OL579866A"},"seq":2,"relation":"authors","after_row":{"id":987364002,"name":"François Truffaut","open_library_id":"OL579866A"},"before_row":null},{"key":{"open_library_id":"OL2644956A"},"seq":3,"relation":"authors","after_row":{"id":987364003,"name":"John Brunner","open_library_id":"OL2644956A"},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL1237227W"},"seq":4,"relation":"works","after_row":{"id":987164001,"title":"Aphrodite","cover_id":null,"author_id":987364001,"work_type":"novel","source_type":"open_library","open_library_id":"OL1237227W","first_publish_year":1896,"native_identity_key":"nlscale:20261102:ol:OL1237227W"},"before_row":null},{"key":{"open_library_edition_id":"OL25417526M"},"seq":5,"relation":"editions","after_row":{"id":987264001,"title":"Aphrodite","isbn_10":null,"isbn_13":"9789051080933","work_id":987164001,"cover_id":null,"language":"dut","publisher":"Areopagus","publish_date":null,"open_library_edition_id":"OL25417526M"},"before_row":null},{"key":{"work_id":987164001,"language":"nl"},"seq":6,"relation":"catalog_work_descriptions","after_row":{"text":"In het antieke Alexandrië raken de beeldhouwer Démétrios en de courtisane Chrysis in elkaars ban. Chrysis stelt eisen aan hem voordat zij zijn liefde wil beantwoorden. Zijn pogingen haar voor zich te winnen brengen hem ertoe grenzen te overschrijden en misdaden te plegen. De roman volgt hoe verlangen en de wil om een ander te beheersen hun verhouding veranderen. Kunst, schoonheid en macht vormen de achtergrond van een verbintenis die steeds minder beheersbaar wordt.","work_id":987164001,"evidence":[{"note":"Original1896PierreLouysnovel, exactDutchAreopagusHardcover9789051080933translatedArisJvanBraam. Independentphysica