eiptSha256":"6e20107e71a74f557b6be7787a73fed85077ef110628199f63a454dbff828d36"}],"checkedAt":"2026-11-03T12:51:43.734Z","editionKey":"/books/OL25417526M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987264001,"bound_title":"Aphrodite","reviewed_at":"2026-11-03T12:51:43.702+00:00","bound_isbn13":"9789051080933","evidence_url":"https://data.bibliotheken.nl/id/nbt/p338993207","review_batch":"nl-scale-20261102-065","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987364001},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL3477651W"},"seq":8,"relation":"works","after_row":{"id":987164002,"title":"Hitchcock","cover_id":null,"author_id":987364002,"work_type":null,"source_type":"open_library","open_library_id":"OL3477651W","first_publish_year":1966,"native_identity_key":"nlscale:20261102:ol:OL3477651W"},"before_row":null},{"key":{"open_library_edition_id":"OL26206755M"},"seq":9,"relation":"editions","after_row":{"id":987264002,"title":"Hitchcock/Truffaut","isbn_10":null,"isbn_13":"9789064031960","work_id":987164002,"cover_id":null,"language":"dut","publisher":"International Theatre Bookshop","publish_date":null,"open_library_edition_id":"OL26206755M"},"before_row":null},{"key":{"work_id":987164002,"language":"nl"},"seq":10,"relation":"catalog_work_descriptions","after_row":{"text":"François Truffaut bespreekt met Alfred Hitchcock hoe films worden gemaakt en hoe zij hun publiek meenemen. De gesprekken verbinden herinneringen aan afzonderlijke producties met vragen over het vertellen van een verhaal, de inzet van beelden en het opbouwen van spanning. Truffaut treedt daarbij op als collega die het vak wil begrijpen. Hitchcock kijkt terug op keuzes die hij tijdens zijn loopbaan maakte. Het boek benadert zijn films zo vanuit het werk van een maker, met de medewerking van Helen Scott.","work_id"