0261102:ol:OL15895132W"},"seq":16,"relation":"works","after_row":{"id":987164004,"title":"The art of raw living food","cover_id":13460368,"author_id":987340002,"work_type":null,"source_type":"open_library","open_library_id":"OL15895132W","first_publish_year":null,"native_identity_key":"nlscale:20261102:ol:OL15895132W"},"before_row":null},{"key":{"open_library_edition_id":"OL47091314M"},"seq":17,"relation":"editions","after_row":{"id":987264004,"title":"Raw food als levenskunst","isbn_10":null,"isbn_13":"9789085081449","work_id":987164004,"cover_id":13460368,"language":"dut","publisher":"Koppenhol Uitgeverij b.v.","publish_date":null,"open_library_edition_id":"OL47091314M"},"before_row":null},{"key":{"work_id":987164004,"language":"nl"},"seq":18,"relation":"catalog_work_descriptions","after_row":{"text":"Doreen Virtue en kok Jenny Ross laten zien hoe rauwe ingrediënten tot uiteenlopende gerechten kunnen worden verwerkt. Fruit, groenten, noten en zaden vormen de basis voor recepten die verder gaan dan een eenvoudige salade. Het boek behandelt onder meer dranken, gemarineerde groenten, kleine hapjes en zoete gerechten. Ook bereidingen die doen denken aan brood, pizza of lasagne krijgen een plaats. De hoofdstukken ordenen het materiaal naar gangen en toepassingen. Het gaat om een praktische kennismaking met deze manier van voedsel bereiden.","work_id":987164004,"evidence":[{"note":"ExactDutch2009Paperback9789085081449, DoreenVirtueprimaryandJennyRosscoauthor confirmedDonnerandindependentNAVS/PRHcatalogue. Practicalcookbook, no verifiedtastefeaturesorhealthclaims, work_typeNULL. OriginalyearleftunknowninsteadofusingDutchtranslationdate.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p321664264"],"reference":"new-work-dossier-readings-065.json#195","checked_at":"2026-11-03T12:51:43.702Z"},{"type":"original_substantive_source_review","review":"content-amendment-030.json","sources":["https://www.donner.nl/producten/raw-food-als-